<section class="page-section"><div class="container narrow"><div class="section-title"><div><p class="eyebrow"><?= e(__('CẬP NHẬT CỦA BẠN')) ?></p><h1><?= e(__('Thông báo')) ?></h1></div><a class="btn btn-ghost" href="<?= e(url('/bookings')) ?>"><?= e(__('Xem chuyến đi')) ?></a></div>
<?php if(!$notifications): ?><div class="empty-state"><h2><?= e(__('Chưa có thông báo')) ?></h2><p><?= e(__('Cập nhật booking sẽ xuất hiện ở đây.')) ?></p></div><?php endif; ?>
<?php foreach($notifications as $notification): $conversationKind=['checkin_reminder'=>__('Nhắc lịch'),'booking_message'=>__('Tin nhắn')][$notification['event_type']]??null; ?><article class="surface-card mb-3<?= $conversationKind?' notification-'.e(str_replace('_','-',$notification['event_type'])):'' ?>"><h2 class="h5"><?php if($conversationKind): ?><span class="notification-kind"><?= e($conversationKind) ?></span> <?php endif; ?><?= e(__((string)$notification['title'])) ?></h2><p><?= e(__((string)$notification['body'])) ?></p><small><?= e(display_date($notification['created_at'],true)) ?> · <?= e($notification['read_at']?__('Đã đọc'):__('Chưa đọc')) ?></small><div class="action-row mt-2">
<?php if($notification['booking_id']): ?><a class="btn btn-outline-primary" href="<?= e(url('/bookings/'.$notification['booking_id'].($notification['event_type']==='booking_message'?'#booking-messages':''))) ?>"><?= e($notification['event_type']==='booking_message'?__('Xem tin nhắn'):__('Xem booking')) ?></a><?php endif; ?>
